class Allocator:
    def __init__(self, n: int):
        self.mem = [0] * n
    def allocate(self, size: int, mID: int) -> int:
        run = 0
        for i, v in enumerate(self.mem):
            run = run + 1 if v == 0 else 0
            if run == size:
                for j in range(i - size + 1, i + 1):
                    self.mem[j] = mID
                return i - size + 1
        return -1
    def freeMemory(self, mID: int) -> int:
        cnt = 0
        for i, v in enumerate(self.mem):
            if v == mID:
                self.mem[i] = 0
                cnt += 1
        return cnt

