import bisect
class Allocator:
    def __init__(self, n: int):
        self.free = [[0, n]]  # [start, end) intervals
        self.blocks = {}
    def allocate(self, size: int, mID: int) -> int:
        for idx, (s, e) in enumerate(self.free):
            if e - s >= size:
                self.blocks.setdefault(mID, []).append([s, s + size])
                if e - s == size:
                    self.free.pop(idx)
                else:
                    self.free[idx] = [s + size, e]
                return s
        return -1
    def freeMemory(self, mID: int) -> int:
        cnt = 0
        for s, e in self.blocks.pop(mID, []):
            cnt += e - s
            pos = bisect.bisect(self.free, [s, float('inf')])
            self.free.insert(pos, [s, e])
            if pos + 1 < len(self.free) and self.free[pos+1][0] == e:
                self.free[pos][1] = self.free[pos+1][1]; self.free.pop(pos+1)
            if pos > 0 and self.free[pos-1][1] == s:
                self.free[pos-1][1] = self.free[pos][1]; self.free.pop(pos)
        return cnt

