class Allocator {
    vector<pair<int,int>> freeIvs; // sorted, disjoint [start,end)
    unordered_map<int, vector<pair<int,int>>> blocks;
public:
    Allocator(int n) { freeIvs.push_back({0, n}); }
    int allocate(int size, int mID) {
        for (int i = 0; i < freeIvs.size(); i++) {
            auto [s, e] = freeIvs[i];
            if (e - s >= size) {
                blocks[mID].push_back({s, s + size});
                if (e - s == size) freeIvs.erase(freeIvs.begin() + i);
                else freeIvs[i] = {s + size, e};
                return s;
            }
        }
        return -1;
    }
    int freeMemory(int mID) {
        int cnt = 0;
        for (auto [s, e] : blocks[mID]) {
            cnt += e - s;
            int pos = upper_bound(freeIvs.begin(), freeIvs.end(), make_pair(s, INT_MAX)) - freeIvs.begin();
            freeIvs.insert(freeIvs.begin() + pos, {s, e});
            if (pos + 1 < freeIvs.size() && freeIvs[pos+1].first == e) {
                freeIvs[pos].second = freeIvs[pos+1].second; freeIvs.erase(freeIvs.begin()+pos+1);
            }
            if (pos > 0 && freeIvs[pos-1].second == s) {
                freeIvs[pos-1].second = freeIvs[pos].second; freeIvs.erase(freeIvs.begin()+pos);
            }
        }
        blocks.erase(mID);
        return cnt;
    }
};

