class Allocator {
    private List<int[]> freeIvs = new ArrayList<>();
    private Map<Integer, List<int[]>> blocks = new HashMap<>();
    public Allocator(int n) { freeIvs.add(new int[]{0, n}); }
    public int allocate(int size, int mID) {
        for (int i = 0; i < freeIvs.size(); i++) {
            int[] iv = freeIvs.get(i);
            if (iv[1] - iv[0] >= size) {
                blocks.computeIfAbsent(mID, k -> new ArrayList<>()).add(new int[]{iv[0], iv[0] + size});
                if (iv[1] - iv[0] == size) freeIvs.remove(i);
                else freeIvs.set(i, new int[]{iv[0] + size, iv[1]});
                return iv[0];
            }
        }
        return -1;
    }
    public int freeMemory(int mID) {
        int cnt = 0;
        List<int[]> bl = blocks.remove(mID);
        if (bl == null) return 0;
        for (int[] b : bl) {
            cnt += b[1] - b[0];
            int pos = 0;
            while (pos < freeIvs.size() && freeIvs.get(pos)[0] < b[0]) pos++;
            freeIvs.add(pos, b);
            if (pos + 1 < freeIvs.size() && freeIvs.get(pos+1)[0] == b[1]) {
                freeIvs.get(pos)[1] = freeIvs.get(pos+1)[1]; freeIvs.remove(pos+1);
            }
            if (pos > 0 && freeIvs.get(pos-1)[1] == b[0]) {
                freeIvs.get(pos-1)[1] = freeIvs.get(pos)[1]; freeIvs.remove(pos);
            }
        }
        return cnt;
    }
}

