var Allocator = function(n) {
    this.free = [[0, n]];
    this.blocks = new Map();
};
Allocator.prototype.allocate = function(size, mID) {
    for (let i = 0; i < this.free.length; i++) {
        const [s, e] = this.free[i];
        if (e - s >= size) {
            if (!this.blocks.has(mID)) this.blocks.set(mID, []);
            this.blocks.get(mID).push([s, s + size]);
            if (e - s === size) this.free.splice(i, 1);
            else this.free[i] = [s + size, e];
            return s;
        }
    }
    return -1;
};
Allocator.prototype.freeMemory = function(mID) {
    let cnt = 0;
    const bl = this.blocks.get(mID) || [];
    this.blocks.delete(mID);
    for (const [s, e] of bl) {
        cnt += e - s;
        let pos = 0;
        while (pos < this.free.length && this.free[pos][0] < s) pos++;
        this.free.splice(pos, 0, [s, e]);
        if (pos + 1 < this.free.length && this.free[pos+1][0] === e) {
            this.free[pos][1] = this.free[pos+1][1]; this.free.splice(pos+1, 1);
        }
        if (pos > 0 && this.free[pos-1][1] === s) {
            this.free[pos-1][1] = this.free[pos][1]; this.free.splice(pos, 1);
        }
    }
    return cnt;
};
